    [updateService],
  );

  return {
    services,
    status,
    loadError,
    reload,
    createService,
    updateService,
    deactivateService,
    reactivateService,
  };
}
import React, { useState } from 'react';
import type { AdminService, ServiceChanges, ServiceInput } from '../../hooks/useAdminServices';
import AdminForm, { FormField } from '../AdminForm';
import {
  parseDuration,
  parsePrice,
  priceToInput,
  validateDuration,
  validatePrice,
  validateServiceName,
} from '../../utils/serviceValidation';

// Formulário de criação e de edição de um serviço (SPEC/2026-11-23-painel-servicos.md).

export type ServiceFields = { name: string; description: string; price: string; duration: string };

type Props = {
  /** Serviço em edição. Sem ele, o formulário cria um serviço novo. */
  service?: AdminService;
  /** Criação: recebe todos os campos. Edição: só os que mudaram. */
  onSave: (data: ServiceInput | ServiceChanges) => Promise<unknown>;
  onCancel: () => void;
};

/** Campos do formulário no formato da API. Só chamar depois de validar. */
export function serviceInput(fields: ServiceFields): ServiceInput {
  return {
    name: fields.name.trim(),
    description: fields.description.trim() || null,
    price: parsePrice(fields.price) as string,
    duration_minutes: parseDuration(fields.duration) as number,
  };
}

/** Campos alterados em relação ao serviço salvo. O preço é comparado pelo valor. */
export function serviceChanges(service: AdminService, fields: ServiceFields): ServiceChanges {
  const input = serviceInput(fields);
  const changes: ServiceChanges = {};
  if (input.name !== service.name) changes.name = input.name;
  if (input.description !== (service.description || null)) changes.description = input.description;
  if (Number(input.price) !== Number(service.price)) changes.price = input.price;
  if (input.duration_minutes !== service.duration_minutes) changes.duration_minutes = input.duration_minutes;
  return changes;
}

function initialFields(service?: AdminService): ServiceFields {
  if (!service) return { name: '', description: '', price: '', duration: '' };
  return {
    name: service.name,
    description: service.description ?? '',
    price: priceToInput(service.price),
    duration: String(service.duration_minutes),
  };
}

const ServiceForm = ({ service, onSave, onCancel }: Props) => {
  const [fields, setFields] = useState<ServiceFields>(() => initialFields(service));

  const set = (key: keyof ServiceFields) => (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => setFields((current) => ({ ...current, [key]: event.target.value }));

  const save = async () => {
    const data = service ? serviceChanges(service, fields) : serviceInput(fields);
    if (Object.keys(data).length === 0) return false;
    await onSave(data);
    return true;
  };

  return (
    <AdminForm
      title={service ? 'Editar serviço' : 'Novo serviço'}
      submitLabel="Salvar serviço"
      errorFallback="Não foi possível salvar o serviço."
      validate={() => validateServiceName(fields.name) ?? validatePrice(fields.price) ?? validateDuration(fields.duration)}
      save={save}
      onCancel={onCancel}
    >
      <FormField id="servico-nome" label="Nome" wide>
        <input id="servico-nome" value={fields.name} onChange={set('name')} />
      </FormField>

      <FormField id="servico-descricao" label="Descrição (opcional)" wide>
        <textarea id="servico-descricao" rows={2} value={fields.description} onChange={set('description')} />
      </FormField>

      <FormField id="servico-preco" label="Preço (R$)">
        <input id="servico-preco" inputMode="decimal" placeholder="35,00" value={fields.price} onChange={set('price')} />
      </FormField>

      <FormField id="servico-duracao" label="Duração (min)">
        <input id="servico-duracao" inputMode="numeric" placeholder="30" value={fields.duration} onChange={set('duration')} />
      </FormField>
    </AdminForm>
  );
};

export default ServiceForm;
import shared from '../../pages/AdminShared.module.css';
import { StatusBadge } from '../AdminForm';
import ConfirmButton from '../ConfirmButton';
import type { AdminService } from '../../hooks/useAdminServices';
import { formatPrice } from '../../utils/serviceValidation';
import styles from './Services.module.css';

// Uma linha da tabela de serviços do painel (SPEC/2026-11-23-painel-servicos.md).
// "Desativar" pede confirmação na própria linha (ConfirmButton). "Reativar" não pede.

type Props = {
  service: AdminService;
  /** Uma ação desta linha está em andamento: os botões ficam desabilitados. */
  busy: boolean;
  onEdit: (service: AdminService) => void;
  onDeactivate: (service: AdminService) => void;
  onReactivate: (service: AdminService) => void;
};

const ServiceRow = ({ service, busy, onEdit, onDeactivate, onReactivate }: Props) => {
  const edit = (
    <button className={shared.btnIcon} onClick={() => onEdit(service)} disabled={busy}>
      Editar
    </button>
  );
  const actions = service.is_active ? (
    <ConfirmButton label="Desativar" question="Desativar este serviço?" onConfirm={() => onDeactivate(service)} busy={busy}>
      {edit}
    </ConfirmButton>
  ) : (
    <>
      {edit}
      <button className={shared.btnIcon} onClick={() => onReactivate(service)} disabled={busy}>
        Reativar
      </button>
    </>
  );

  return (
    <tr className={service.is_active ? undefined : styles.inactive} aria-label={service.name}>
      <td style={{ color: '#fff', fontWeight: 500 }}>
        {service.name}
        {service.description && <span className={styles.description}>{service.description}</span>}
      </td>
      <td>{service.duration_minutes} min</td>
      <td>{formatPrice(service.price)}</td>
      <td>
        <StatusBadge active={service.is_active} />
      </td>
      <td>{actions}</td>
    </tr>
  );
};

export default ServiceRow;
// Validação e conversão dos campos do formulário de serviço do painel, com as regras do
// backend (src/backend/modules/services/schemas.py; SPEC/2026-11-23-painel-servicos.md).
// Cada validate* devolve a mensagem de erro, ou null quando o valor serve.

export const NAME_MIN = 2;
export const NAME_MAX = 100;
export const DURATION_MAX = 720;
/** Dígitos da parte inteira que cabem no Numeric(10, 2) da coluna: até 99.999.999. */
const PRICE_INT_DIGITS = 8;

// Só dígitos, com um separador decimal (vírgula ou ponto) e até 2 casas. Sem milhar.
const PRICE_FORMAT = /^(\d+)(?:[.,](\d{1,2}))?$/;

export const NAME_ERROR = `Nome deve ter entre ${NAME_MIN} e ${NAME_MAX} caracteres`;
export const PRICE_ERROR = 'Preço deve ser um valor entre 0 e 99.999.999,99, com até 2 casas decimais';
export const DURATION_ERROR = `Duração deve ser um número inteiro de 1 a ${DURATION_MAX} minutos`;

export function validateServiceName(name: string): string | null {
  const length = name.trim().length;
  return length < NAME_MIN || length > NAME_MAX ? NAME_ERROR : null;
}

/**
 * Preço digitado ("35", "35,5", "35.50") no formato da API, com 2 casas ("35.50"),
 * ou null quando não serve. Converte o texto sem passar por float, para não arredondar.
 */
export function parsePrice(text: string): string | null {
  const match = PRICE_FORMAT.exec(text.trim());
  if (!match) return null;
  const integer = match[1].replace(/^0+(?=\d)/, '');
  if (integer.length > PRICE_INT_DIGITS) return null;
  return `${integer}.${(match[2] ?? '').padEnd(2, '0')}`;
}

export function validatePrice(text: string): string | null {
  return parsePrice(text) === null ? PRICE_ERROR : null;
}

/** Duração digitada como inteiro, ou null quando não é um inteiro de 1 a 720. */
export function parseDuration(text: string): number | null {
  const value = text.trim();
  if (!/^\d+$/.test(value)) return null;
  const minutes = Number(value);
  return minutes >= 1 && minutes <= DURATION_MAX ? minutes : null;
}

export function validateDuration(text: string): string | null {
  return parseDuration(text) === null ? DURATION_ERROR : null;
}

/** Preço da API ("35.00" ou 35) para mostrar no campo do formulário ("35,00"). */
export function priceToInput(price: string | number): string {
  return Number(price).toFixed(2).replace('.', ',');
}

/** Preço da API para a tabela, em reais ("R$ 35,00"). */
export function formatPrice(price: string | number): string {
  return Number(price).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

