import { Navigate } from 'react-router-dom';
import { accountFallback } from '../components/account/accountFallback';
import MyAppointments from '../components/account/MyAppointments';
import NotificationsList from '../components/account/NotificationsList';
import PasswordForm from '../components/account/PasswordForm';
import ProfileForm from '../components/account/ProfileForm';
import styles from '../components/account/Account.module.css';
import { useAccount, type AccountUser } from '../hooks/useAccount';
import { CHANGE_PASSWORD_PATH } from '../utils/afterLogin';
import { ROLE_LABELS } from '../utils/roles';

// "Minha conta": dados pessoais e troca de senha (SPEC/2026-11-22-auth-perfil-senha.md).
// Serve ao cliente em /conta e ao admin e ao barbeiro em /admin/conta. Só o cliente vê
// "Meus agendamentos" (SPEC/2026-11-25-meus-agendamentos.md).

type Props = {
  /** Para onde mandar quem não está logado. */
  loginPath: string;
};

const Avatar = ({ user }: { user: AccountUser }) =>
  user.avatar_url ? (
    <img className={styles.avatar} src={user.avatar_url} alt="" />
  ) : (
    <div className={styles.avatar} aria-hidden="true">
      {user.full_name.trim().charAt(0).toUpperCase()}
    </div>
  );

const Account = ({ loginPath }: Props) => {
  const account = useAccount();
  const { user, saveProfile, changePassword } = account;

  const fallback = accountFallback(account, loginPath);
  if (fallback || !user) return fallback;
  if (user.must_change_password) return <Navigate to={CHANGE_PASSWORD_PATH} replace />;

  return (
    <div className={styles.page}>
      <header className={styles.header}>
        <Avatar user={user} />
        <div className={styles.identity}>
          <h1>Minha conta</h1>
          <p className={styles.email}>
            {user.email} · {ROLE_LABELS[user.role]}
          </p>
        </div>
      </header>

      {!user.email_verified && (
        <p className={styles.warning}>Seu e-mail ainda não foi verificado.</p>
      )}

      {user.role === 'client' && <MyAppointments />}
      <ProfileForm user={user} onSave={saveProfile} />
      <PasswordForm onChangePassword={changePassword} />
      <NotificationsList />
    </div>
  );
};

export default Account;
import { useState } from 'react';
import { useMyAppointments, type MyAppointment } from '../../hooks/useMyAppointments';
import { apiErrorMessage } from '../../utils/apiError';
import { splitByStart } from '../../utils/appointmentStatus';
import AppointmentItem from './AppointmentItem';
import styles from './Account.module.css';

// "Meus agendamentos" na conta do cliente (SPEC/2026-11-25-meus-agendamentos.md): próximos e
// anteriores, com o cancelamento pelo PUT /appointments/{id}/cancel.

type GroupProps = {
  title: string;
  empty: string;
  appointments: MyAppointment[];
  barberNames: Record<string, string>;
  busyId: string | null;
  onCancel: (appointment: MyAppointment) => void;
};

const AppointmentGroup = ({ title, empty, appointments, barberNames, busyId, onCancel }: GroupProps) => (
  <div className={styles.group}>
    <h3>{title}</h3>
    {appointments.length === 0 ? (
      <p className={styles.hint}>{empty}</p>
    ) : (
      <ul className={styles.list} aria-label={title}>
        {appointments.map((a) => (
          <AppointmentItem
            key={a.id}
            appointment={a}
            barberName={barberNames[a.barber_id] ?? 'Barbeiro'}
            busy={busyId !== null}
            onCancel={onCancel}
          />
        ))}
      </ul>
    )}
  </div>
);

const MyAppointments = () => {
  const { appointments, barberNames, status, loadError, reload, cancelAppointment } = useMyAppointments();
  const [busyId, setBusyId] = useState<string | null>(null);
  const [actionError, setActionError] = useState('');
  const [notice, setNotice] = useState('');

  const cancel = async (appointment: MyAppointment) => {
    setBusyId(appointment.id);
    setActionError('');
    setNotice('');
    try {
      await cancelAppointment(appointment.id);
      setNotice('Agendamento cancelado.');
    } catch (err) {
      setActionError(apiErrorMessage(err, 'Não foi possível cancelar o agendamento.'));
    } finally {
      setBusyId(null);
    }
  };

  const { upcoming, past } = splitByStart(appointments);
  const groupProps = { barberNames, busyId, onCancel: cancel };

  return (
    <section className={styles.card} aria-labelledby="agendamentos-titulo">
      <h2 id="agendamentos-titulo">Meus agendamentos</h2>

      {status === 'loading' && <p>Carregando...</p>}
      {status === 'error' && (
        <>
          <p className={styles.error} role="alert">
            {loadError}
          </p>
          <div className={styles.actions}>
            <button type="button" className={styles.submit} onClick={reload}>
              Tentar de novo
            </button>
          </div>
        </>
      )}

      {status === 'ready' && (
        <>
          {actionError && (
            <p className={styles.error} role="alert">
              {actionError}
            </p>
          )}
          {notice && (
            <p className={styles.success} role="status">
              {notice}
            </p>
          )}
          <AppointmentGroup title="Próximos" empty="Nenhum agendamento marcado." appointments={upcoming} {...groupProps} />
          <AppointmentGroup title="Anteriores" empty="Nenhum agendamento anterior." appointments={past} {...groupProps} />
        </>
      )}
    </section>
  );
};

export default MyAppointments;
import type { ReactElement } from 'react';
import { Navigate } from 'react-router-dom';
import type { AccountStatus } from '../../hooks/useAccount';
import styles from './Account.module.css';

// O que as telas da própria conta mostram enquanto ela não está pronta: o login para quem não
// está logado, "Carregando..." ou o erro. Usado por "Minha conta" e pela troca obrigatória de
// senha (SPEC/2026-11-25-admin-usuarios.md).

type Account = { user: unknown; status: AccountStatus; loadError: string };

/** O elemento a mostrar no lugar da tela, ou null quando a conta está pronta. */
export function accountFallback({ user, status, loadError }: Account, loginPath: string): ReactElement | null {
  if (status === 'unauthenticated') return <Navigate to={loginPath} replace />;
  if (status === 'loading') return <p className={styles.page}>Carregando...</p>;
  if (status === 'error' || !user) {
    return (
      <p className={`${styles.page} ${styles.error}`} role="alert">
        {loadError}
      </p>
    );
  }
  return null;
}
import { useCallback } from 'react';
import api from '../api';
import { useApiResource } from './useApiResource';

// Agendamentos do cliente logado em "Minha conta": carga pelo GET /appointments/me e o
// cancelamento pelo PUT /appointments/{id}/cancel (SPEC/2026-11-25-meus-agendamentos.md).
// O cancelamento devolve o agendamento como o backend gravou e lança o erro da API, para
// quem chamou mostrar a mensagem.

export type MyAppointmentItem = {
  id: string;
  service_name: string;
  locked_price: string;
  duration_minutes: number;
};

export type MyAppointment = {
  id: string;
  barber_id: string;
  start_datetime: string;
  end_datetime: string;
  status: string;
  total_price: string;
  items: MyAppointmentItem[];
};

type PublicBarber = { id: string; full_name: string };

/** Nome de cada barbeiro da vitrine. Sem a vitrine, os agendamentos aparecem do mesmo jeito. */
async function loadBarberNames(): Promise<Record<string, string>> {
  try {
    const response = await api.get<PublicBarber[]>('/barbers');
    const barbers = Array.isArray(response.data) ? response.data : [];
    return Object.fromEntries(barbers.map((b) => [b.id, b.full_name]));
  } catch {
    return {};
  }
}

type Loaded = { appointments: MyAppointment[]; barberNames: Record<string, string> };

async function loadMine(): Promise<Loaded> {
  const [response, barberNames] = await Promise.all([api.get<MyAppointment[]>('/appointments/me'), loadBarberNames()]);
  return { appointments: Array.isArray(response.data) ? response.data : [], barberNames };
}

const EMPTY: Loaded = { appointments: [], barberNames: {} };

export function useMyAppointments() {
  const { data, setData, status, loadError, reload } = useApiResource(
    loadMine,
    EMPTY,
    'Não foi possível carregar seus agendamentos.',
  );

  /** Cancela e põe na lista o agendamento como o backend devolveu ("cancelled"). */
  const cancelAppointment = useCallback(async (id: string) => {
    const saved = (await api.put<MyAppointment>(`/appointments/${id}/cancel`)).data;
    setData((current) => ({
      ...current,
      appointments: current.appointments.map((a) => (a.id === saved.id ? saved : a)),
    }));
    return saved;
  }, [setData]);

  return { ...data, status, loadError, reload, cancelAppointment };
}
import { isAxiosError } from 'axios';
import { useCallback, useEffect, useState } from 'react';
import api from '../api';
import { apiErrorMessage } from '../utils/apiError';
import type { UserRole } from '../utils/roles';

// Dados da conta do usuário logado e as duas ações da página "Minha conta"
// (SPEC/2026-11-22-auth-perfil-senha.md).

export type AccountUser = {
  id: string;
  email: string;
  full_name: string;
  phone: string | null;
  avatar_url: string | null;
  role: UserRole;
  email_verified: boolean;
  /** Senha temporária ainda não trocada (SPEC/2026-11-25-admin-usuarios.md). */
  must_change_password?: boolean;
};

export type ProfileChanges = Partial<Pick<AccountUser, 'full_name' | 'phone' | 'avatar_url'>>;

export type AccountStatus = 'loading' | 'ready' | 'unauthenticated' | 'error';

export function useAccount() {
  const [user, setUser] = useState<AccountUser | null>(null);
  const [status, setStatus] = useState<AccountStatus>('loading');
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    let active = true;
    api
      .get<AccountUser>('/auth/me')
      .then((response) => {
        if (!active) return;
        setUser(response.data);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        // 401 depois do refresh falhar, ou 403 sem token: precisa entrar de novo.
        const code = isAxiosError(error) ? error.response?.status : undefined;
        if (code === 401 || code === 403) {
          setStatus('unauthenticated');
        } else {
          setLoadError(apiErrorMessage(error, 'Não foi possível carregar seus dados.'));
          setStatus('error');
        }
      });
    return () => {
      active = false;
    };
  }, []);

  /** Envia só os campos alterados e passa a mostrar o usuário como o backend devolveu. */
  const saveProfile = useCallback(async (changes: ProfileChanges) => {
    const response = await api.put<AccountUser>('/auth/me', changes);
    setUser(response.data);
    return response.data;
  }, []);

  /** Troca a senha e devolve a mensagem de confirmação do backend. */
  const changePassword = useCallback(async (currentPassword: string, newPassword: string) => {
    const response = await api.put<{ message: string }>('/auth/me/password', {
      current_password: currentPassword,
      new_password: newPassword,
    });
    return response.data.message;
  }, []);

  return { user, status, loadError, saveProfile, changePassword };
}
